"""Generated by solo-to-scale; edit `templates/tools/check_governance.py` in the plugin, then run upgrade.

Governance check for the operating protocol (run in CI, or as `python tools/check_governance.py`).

Fails if:
  1. a decision ID cited in the branch's commit messages or changed Markdown files is in no register
  2. a register row has a status outside Approved, Proposed, Assumption, Open (plus `approved_words`)
  3. the protocol's lifecycle line appears in any tracked file but founder/operating-protocol.md
     (founder/prompts/ is exempt: the saved prompts describe this rule)
  4. a stage or slice is newly marked done (playbook "Passed", slices.json "done") without a HANDOFF.md change
  5. founder/roadmap.json, founder/team.json or founder/traceability.json is out of date with its sources
  6. AGENTS.md plus the root CLAUDE.md, or any other CLAUDE.md, is longer than `claude_md_max_lines`
Warns (never fails) if:
  - founder/status.md "Last updated" is older than `status_stale_days`
  - the branch changes more than `pr_warn_lines` lines, not counting generated and lock files
Standard library only. Limits live in .claude/governance.json.
"""
from __future__ import annotations

import argparse
import datetime as dt
import json
import os
import re
import sys
from pathlib import Path

sys.path.insert(0, str(Path(__file__).resolve().parent))
import _s2s as s  # noqa: E402
import build_roadmap  # noqa: E402
import build_team  # noqa: E402
import build_traceability  # noqa: E402

PROTOCOL = "founder/operating-protocol.md"
# Built from parts, so this file doesn't contain the lifecycle line itself.
PROTOCOL_MARKER = " → ".join(["Define", "Analyse", "Decide"])
CITED = re.compile(r"\b([A-Z]-\d{2,})\b")
VIEW_DATA = {"founder/roadmap.json": build_roadmap, "founder/team.json": build_team,
             "founder/traceability.json": build_traceability}


def lines(path: Path) -> int:
    return len(s.read(path).splitlines())


def instruction_size(root: Path, cfg: dict, tracked: list[str]) -> list[str]:
    limit = int(cfg.get("claude_md_max_lines") or 200)
    errors = []
    total = lines(root / "AGENTS.md") + lines(root / "CLAUDE.md")
    if total > limit:
        errors.append(f"AGENTS.md + CLAUDE.md are {total} lines together; keep them at or under {limit} "
                      "(move area rules into a subdirectory CLAUDE.md)")
    for name in tracked:
        if name.endswith("CLAUDE.md") and name != "CLAUDE.md" and lines(root / name) > limit:
            errors.append(f"{name} is {lines(root / name)} lines; keep it at or under {limit}")
    return errors


def done_slices(text: str | None) -> set[str]:
    try:
        data = json.loads(text or "{}")
    except ValueError:
        return set()
    return {str(x.get("id")) for x in (data.get("slices") or []) if isinstance(x, dict) and x.get("status") == "done"}


def passed_stages(text: str | None) -> set[str]:
    return {f"stage {r['#']}" for t in s.tables(text or "") for r in t
            if r.get("#", "").isdigit() and r.get("status", "").lower() == "passed"}


def check(root: Path, base_ref: str, today: dt.date) -> tuple[list[str], list[str]]:
    cfg = s.config(root)
    errors: list[str] = []
    warnings: list[str] = []
    allowed = set(s.STATUSES) | set(cfg.get("approved_words") or [])

    rows = s.decisions(root, cfg)
    known = {r["id"] for r in rows}
    for r in rows:
        if r["status"] and r["status"] not in allowed:
            errors.append(f"{r['register']}: {r['id']} has status '{r['status']}'; use one of {sorted(allowed)}")
        if not r["status"] and r["has_status"]:
            errors.append(f"{r['register']}: {r['id']} has no status")
    prefixes = {r["id"].split("-")[0] for r in rows} | {"B", "D"}

    tracked = (s.git(root, "ls-files") or "").splitlines()
    for name in tracked:
        if name == PROTOCOL or name.startswith("founder/prompts/"):
            continue
        path = root / name
        try:
            if path.stat().st_size > 2_000_000:
                continue
            text = path.read_text(encoding="utf-8", errors="ignore")
        except OSError:
            continue
        if PROTOCOL_MARKER in text:
            errors.append(f"{name}: restates the protocol ('{PROTOCOL_MARKER}'); point to {PROTOCOL} instead")

    errors += instruction_size(root, cfg, tracked)

    for rel, mod in VIEW_DATA.items():
        if (root / rel).exists() and s.read(root / rel) != s.dump(mod.build(root)):
            errors.append(f"{rel} is out of date with its sources; run tools/{mod.__name__}.py and commit it")

    base = (s.git(root, "merge-base", base_ref, "HEAD") or "").strip()
    if not base:
        warnings.append(f"base '{base_ref}' not found; skipped the branch checks (fetch it first)")
    else:
        handoff_changed = bool((s.git(root, "diff", "--name-only", base, "HEAD", "--", "HANDOFF.md") or "").strip())
        rel = str(cfg.get("slices_file") or "founder/slices.json")
        newly = sorted(done_slices(s.git(root, "show", f"HEAD:{rel}")) - done_slices(s.git(root, "show", f"{base}:{rel}")))
        newly += sorted(passed_stages(s.git(root, "show", "HEAD:founder/playbook.md"))
                        - passed_stages(s.git(root, "show", f"{base}:founder/playbook.md")))
        if newly and not handoff_changed:
            errors.append(f"{', '.join(newly)} marked done but HANDOFF.md not changed; run the handoff skill")

        sources = [("commit messages", s.git(root, "log", "--format=%B", f"{base}..HEAD") or "")]
        changed = (s.git(root, "diff", "--name-only", "--diff-filter=AMR", base, "HEAD") or "").split()
        sources += [(n, s.read(root / n)) for n in changed if n.endswith(".md") and (root / n).exists()]
        for where, text in sources:
            for rid in sorted({x for x in CITED.findall(text) if x.split("-")[0] in prefixes} - known):
                errors.append(f"{where}: cites {rid}, which no register defines")

        total = 0
        for line in (s.git(root, "diff", "--numstat", base, "HEAD") or "").splitlines():
            parts = line.split("\t")
            if len(parts) == 3 and parts[0].isdigit() and not s.is_generated(parts[2], cfg):
                total += int(parts[0]) + int(parts[1])
        limit = int(cfg.get("pr_warn_lines") or 400)
        if total > limit:
            warnings.append(f"this branch changes {total} lines (over {limit}, not counting generated files); "
                            "consider splitting the PR")

    status = s.read(root / "founder" / "status.md")
    if status:
        m = re.search(r"Last updated:\s*(\d{4}-\d{2}-\d{2})", status)
        days = int(cfg.get("status_stale_days") or 14)
        if not m:
            warnings.append("founder/status.md has no 'Last updated: YYYY-MM-DD' line")
        elif (today - dt.date.fromisoformat(m.group(1))).days > days:
            warnings.append(f"founder/status.md last updated {m.group(1)}, more than {days} days ago")
    return errors, warnings


def main(argv: list[str] | None = None) -> int:
    ap = argparse.ArgumentParser(description="Governance check for the operating protocol")
    ap.add_argument("--base", default=os.environ.get("GOVERNANCE_BASE", "origin/main"))
    ap.add_argument("--root", type=Path, default=s.ROOT)
    args = ap.parse_args(argv)
    errors, warnings = check(args.root, args.base, dt.date.today())
    gha = os.environ.get("GITHUB_ACTIONS") == "true"
    for w in warnings:
        print(f"::warning::{w}" if gha else f"warning: {w}")
    for e in errors:
        print(f"::error::{e}" if gha else f"error: {e}")
    print("governance: FAILED" if errors else "governance: OK")
    return 1 if errors else 0


if __name__ == "__main__":
    sys.exit(main())
